import React, { useState, useRef, useEffect } from 'react';
import { Select, Input } from 'antd';
import { airports } from './data/airports';

const HybridPathInput = ({ value, onChange, placeholder = 'Enter path (e.g. NRT/HND-OAK/SFO-JFK/EWR)' }) => {
  const [inputValue, setInputValue] = useState(value || '');
  const [showDropdown, setShowDropdown] = useState(false);
  const [currentSearch, setCurrentSearch] = useState('');
  const [cursorPosition, setCursorPosition] = useState(0);
  const inputRef = useRef(null);

  // Convert airports data to options format
  const airportOptions = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name} (${airport.Country})`
  }));

  // Filter airports based on current search
  const filteredOptions = airportOptions.filter(option => {
    const searchLower = currentSearch.toLowerCase();
    return option.value.toLowerCase().includes(searchLower) || 
           option.label.toLowerCase().includes(searchLower);
  });

  // Handle input change
  const handleInputChange = (e) => {
    const newValue = e.target.value;
    const newPosition = e.target.selectionStart;
    
    setInputValue(newValue);
    setCursorPosition(newPosition);
    
    // Find the current word being typed
    const beforeCursor = newValue.slice(0, newPosition);
    const words = beforeCursor.split(/[/-]/);
    const currentWord = words[words.length - 1].trim();
    
    if (currentWord && !['/', '-'].includes(currentWord)) {
      setCurrentSearch(currentWord);
      setShowDropdown(true);
    } else {
      setShowDropdown(false);
    }
    
    onChange?.(newValue);
  };

  // Handle airport selection
  const handleSelect = (selectedValue) => {
    const beforeCursor = inputValue.slice(0, cursorPosition);
    const afterCursor = inputValue.slice(cursorPosition);
    
    // Find the last separator before the cursor
    const lastSeparatorIndex = Math.max(
      beforeCursor.lastIndexOf('/'),
      beforeCursor.lastIndexOf('-')
    );
    
    // Replace the current word with the selected airport
    const newValue = beforeCursor.slice(0, lastSeparatorIndex + 1) + 
                    selectedValue + 
                    afterCursor;
    
    setInputValue(newValue);
    setShowDropdown(false);
    onChange?.(newValue);
    
    // Focus back on input and place cursor after the selected airport
    setTimeout(() => {
      if (inputRef.current) {
        inputRef.current.focus();
        const newPosition = lastSeparatorIndex + 1 + selectedValue.length;
        inputRef.current.setSelectionRange(newPosition, newPosition);
      }
    }, 0);
  };

  // Handle key down
  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && showDropdown && filteredOptions.length > 0) {
      e.preventDefault();
      handleSelect(filteredOptions[0].value);
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
    }
  };

  // Handle blur
  const handleBlur = () => {
    // Delay hiding dropdown to allow for selection
    setTimeout(() => {
      setShowDropdown(false);
    }, 200);
  };

  // Handle focus
  const handleFocus = () => {
    if (currentSearch) {
      setShowDropdown(true);
    }
  };

  // Render path segments with airport boxes
  const renderPathSegments = () => {
    const segments = inputValue.split(/([/-])/);
    
    return segments.map((segment, index) => {
      if (['/', '-'].includes(segment)) {
        return (
          <span key={index} style={{ 
            margin: '0 4px',
            color: '#666',
            fontWeight: 'normal'
          }}>
            {segment}
          </span>
        );
      }

      // Check if this segment is a valid airport code
      const airport = airports.find(a => a.IATA === segment);
      if (airport) {
        return (
          <span
            key={index}
            style={{
              display: 'inline-block',
              backgroundColor: '#f0f0f0',
              border: '1px solid #d9d9d9',
              borderRadius: '4px',
              padding: '2px 8px',
              margin: '0 2px',
              fontSize: '14px',
              fontWeight: '500',
              color: '#262626',
              boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
            }}
          >
            {segment}
          </span>
        );
      }

      // If not a valid airport, render as plain text
      return (
        <span key={index} style={{ 
          color: '#999',
          fontWeight: 'normal'
        }}>
          {segment}
        </span>
      );
    });
  };

  return (
    <div style={{ position: 'relative' }}>
      <div style={{ 
        minHeight: '32px',
        padding: '4px 11px',
        border: '1px solid #d9d9d9',
        borderRadius: '4px',
        backgroundColor: 'white',
        display: 'flex',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '4px'
      }}>
        {renderPathSegments()}
        <Input
          ref={inputRef}
          value={inputValue}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          onFocus={handleFocus}
          placeholder={placeholder}
          style={{ 
            border: 'none',
            padding: '0',
            flex: '1',
            minWidth: '100px',
            outline: 'none',
            boxShadow: 'none'
          }}
        />
      </div>
      
      {showDropdown && filteredOptions.length > 0 && (
        <div
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            zIndex: 1000,
            backgroundColor: 'white',
            border: '1px solid #d9d9d9',
            borderRadius: '4px',
            boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
            maxHeight: '300px',
            overflow: 'auto',
            marginTop: '4px'
          }}
        >
          {filteredOptions.map(option => (
            <div
              key={option.value}
              style={{
                padding: '8px 12px',
                cursor: 'pointer',
                ':hover': {
                  backgroundColor: '#f5f5f5'
                }
              }}
              onMouseDown={() => handleSelect(option.value)}
            >
              <div style={{ fontWeight: 500 }}>{option.value}</div>
              <div style={{ fontSize: '12px', color: '#666' }}>
                {option.label}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default HybridPathInput;
